        "rows": [
          [
            "Questão",
            "Um esquema mostra rúmen em bovino e ceco em equino. Qual a comparação funcional correta?"
          ],
          [
            "Interpretação",
            "Ambos participam de fermentação microbiana, em posições distintas do trato. No bovino, a fermentação pré-gástrica antecede a digestão intestinal; no equino, ocorre predominantemente no intestino grosso. A posição modifica o aproveitamento dos produtos microbianos."
          ],
          [
            "Base de estudo",
            "DYCE, K. M.; SACK, W. O.; WENSING, C. J. G. Textbook of Veterinary Anatomy. Elsevier."
          ]
        ]
