            "tag": "REVISÃO",
            "title": "Patologia Clínica Veterinária",
            "text": "Num cão anêmico, há aumento de reticulócitos em contagem absoluta segundo o laboratório. O que esse achado acrescenta? Sustenta resposta regenerativa da medula no contexto avaliado. A interpretação continua dependente da magnitude, tempo e demais achados. Regeneração caracteriza resposta, mas não identifica sozinha a causa da anemia."
